mapper.select:
select h.status
  from monitor_hour_check h
 where h.data_hour = #{hour}

mapper.update:
update monitor_hour_check
   set check_count = check_count + 1,
       last_check_at = #{now}
 where site_code = #{scope.siteCode}
   and data_hour = #{hour}
   and status = 'waiting'

update monitor_hour_check
   set status = #{status},
       judged_at = #{now}
 where site_code = #{scope.siteCode}
   and data_hour = #{hour}
   and status = 'waiting'

update monitor_hour_check
   set status = 'missing',
       judged_at = #{now}
 where site_code = #{scope.siteCode}
   and data_hour < #{before}
   and status = 'waiting'

update monitor_rule
   set last_judged_at = #{judgedAt},
       judge_error    = #{judgeError,jdbcType=VARCHAR}
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}

mapper.select:
select count(*)
  from monitor_notify_log n
 where n.event_id = #{eventId}
   and n.notify_type = #{notifyType}
